---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Stat cards: Four headline numbers with sparklines and a period switch.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change stat-cards.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './stat-cards.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'wide', className]} data-c="stat-cards" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="scx">
  <div class="scx-h"><div class="seg2 scx-sg" role="group" aria-label="Period"><button aria-pressed="false" data-v="0">7 days</button><button aria-pressed="true" data-v="1">30 days</button><button aria-pressed="false" data-v="2">Quarter</button></div></div>
  <div class="scx-grid"></div>
</div>
  </Fragment></div>
</div>
<script>
  import './stat-cards.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Stat cards ---------- */
.scx{display:flex;flex-direction:column;gap:10px;width:100%}
.scx-h{display:flex;justify-content:flex-end}
.scx-sg button{font-size:12px;height:26px;padding:0 10px}
.scx-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
@media (max-width:820px){.scx-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
/* phones keep two columns, two rows: a little less padding, and the change chip goes under the number when it can't fit beside it */
@media (max-width:520px){.scx-grid{gap:var(--dm-s-2)}.scx-c{padding:var(--dm-s-3)}.scx-v{flex-wrap:wrap;row-gap:var(--dm-s-1)}.scx-sp{height:28px}}
.scx-c{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:6px;transition:transform .45s var(--dm-ease),box-shadow .3s;min-width:0}
@media (hover:hover) and (pointer:fine){.scx-c:hover{transform:translateY(-2px);box-shadow:var(--dm-shadow-pop)}}
.scx-k{display:flex;align-items:center;gap:6px;font-size:12.5px;color:var(--dm-muted)}
.scx-k .ic{display:grid;color:var(--dm-fg2)}
.scx-v{display:flex;align-items:center;gap:var(--dm-s-2)}
.scx-v b{font-size:14px;font-weight:500;letter-spacing:-.02em}
.scx-d{font-size:12px;font-weight:500}
.scx-d.tag{display:inline-flex;height:20px;padding:0 6px}
.scx-sp{height:34px;margin-top:var(--dm-s-1)}
.scx-sp svg{width:100%;height:100%;overflow:visible}
.scx-sp path{fill:none;stroke-width:1.75;vector-effect:non-scaling-stroke;stroke-linejoin:round;transition:d .8s var(--dm-ease)}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, REDUCE, seg, stagger, swap, tween } from '../core/core.js';
DM.def('stat-cards', (r, c) => {
  const S = [
    ['spark','Agent runs',[[412,12],[1730,18],[4980,22]],'',[3,4,4,5,6,5,7,8]],
    ['users','Active editors',[[318,4],[1130,9],[1620,31]],'',[5,5,6,6,6,7,7,8]],
    ['clock','Hours saved',[[96,15],[402,21],[1180,26]],'h',[2,3,3,4,5,6,6,8]],
    ['coins','Agent spend',[[84,-6],[341,-3],[960,8]],'$',[6,5,6,5,4,4,4,3]]
  ];
  const grid = $('.scx-grid', r); let per = 1;
  grid.innerHTML = S.map((s, i) => `<div class="scx-c panel"><span class="scx-k"><span class="ic">${I(s[0],'xs')}</span>${s[1]}</span><div class="scx-v"><b class="num">0</b><span class="scx-d num"></span></div><div class="scx-sp"><svg viewBox="0 0 100 30" preserveAspectRatio="none"><path stroke="var(--dm-c${i + 1})" d="M0 30 L100 30"/></svg></div></div>`).join('');
  const cards = $$('.scx-c', grid), cur = S.map(() => 0);
  const fmt = (s, v) => s[3] === '$' ? '$' + Math.round(v).toLocaleString('en-US') : Math.round(v).toLocaleString('en-US') + s[3];
  function draw(p){
    per = p; cards.forEach((el, i) => { const s = S[i], [val, ch] = s[2][p];
      tween(cur[i], val, 900, v => { cur[i] = v; $('b', el).textContent = fmt(s, v); });
      const d = $('.scx-d', el); d.className = 'tag scx-d num ' + (ch >= 0 ? 'ok up' : 'bad dn'); swap(d, (ch >= 0 ? '+' : '') + ch + '%');
      const pts = s[4].map((y, k) => { const yy = y + Math.sin(k * 1.7 + p * 2) * (p ? 1 : .5); return `${k === 0 ? 'M' : 'L'}${(k / 7 * 100).toFixed(1)} ${(29 - yy * 3.2).toFixed(1)}`; }).join(' ');
      $('path', el).setAttribute('d', pts); el.dataset.tip = ['vs previous 7 days','vs previous 30 days','vs last quarter'][p]; });
  }
  seg($('.scx-sg', r), v => draw(+v));
  stagger(cards, 70);
  c.later(240, () => draw(1));
  if (!REDUCE) cards.forEach((el, i) => $('.scx-sp svg', el).animate([{ clipPath:'inset(-4px 100% -4px 0)' }, { clipPath:'inset(-4px 0% -4px 0)' }], { duration:1000, delay:300 + i * 70, easing:'cubic-bezier(.45,0,.2,1)', fill:'backwards' }));
});
